30	import org.springframework.http.HttpHeaders;
31	import org.springframework.http.HttpStatus;
32	import org.springframework.http.ResponseEntity;
33	import org.springframework.samples.petclinic.mapper.OwnerMapper;
34	import org.springframework.samples.petclinic.mapper.PetMapper;
35	import org.springframework.samples.petclinic.mapper.VisitMapper;
36	import org.springframework.samples.petclinic.model.Owner;
37	import org.springframework.samples.petclinic.model.Pet;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
40	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
41	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
42	import org.springframework.samples.petclinic.rest.advice.OwnerCityAtCapacityException;
43	import org.springframework.samples.petclinic.rest.api.OwnersApi;
44	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
45	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.PetDto;
47	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /**
69	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
70	     * domain containing at least one dot, with no whitespace in any part.
71	     */
72	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
73	
74	    /**
75	     * Common street-type abbreviations expanded during address normalization. Keys are the
76	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
77	     * expanded form it is replaced with.
78	     */
79	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
80	        "ST", "STREET",
81	        "RD", "ROAD",
82	        "AVE", "AVENUE");
83	
84	    /**
85	     * The maximum number of owners a single city may contain. Once a city holds this many owners it
86	     * is at capacity and cannot take any more.
87	     */
88	    private static final int CITY_CAPACITY = 50;
89	
90	    private final ClinicService clinicService;
91	
92	    private final OwnerMapper ownerMapper;
93	
94	    private final PetMapper petMapper;
95	
96	    private final VisitMapper visitMapper;
97	
98	    public OwnerRestControllerV1(ClinicService clinicService,
99	                                 OwnerMapper ownerMapper,
100	                                 PetMapper petMapper,
101	                                 VisitMapper visitMapper) {
102	        this.clinicService = clinicService;
103	        this.ownerMapper = ownerMapper;
104	        this.petMapper = petMapper;
105	        this.visitMapper = visitMapper;
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
111	        Collection<Owner> owners;
112	        if (lastName != null) {
113	            owners = this.clinicService.findOwnerByLastName(lastName);
114	        } else {
115	            owners = this.clinicService.findAllOwners();
116	        }
117	        if (owners.isEmpty()) {
118	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
119	        }
120	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
126	        Owner owner = this.clinicService.findOwnerById(ownerId);
127	        if (owner == null) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
136	        validateRequiredFields(ownerFieldsDto);
137	        HttpHeaders headers = new HttpHeaders();
138	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
139	        String address = normalizeAddress(ownerFieldsDto.getAddress());
140	        owner.setAddress(address);
141	        rejectCityAtCapacity(owner.getCity());
142	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
143	            assignHousehold(owner, ownerFieldsDto.getLastName(), address);
144	        } else {
145	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), address);
146	        }
147	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
148	        rejectDuplicateTelephone(telephone);
149	        owner.setTelephone(telephone);
150	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
151	        if (owner.getRegistrationDate() == null) {
152	            owner.setRegistrationDate(LocalDate.now());
153	        }
154	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
155	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
156	        this.clinicService.saveOwner(owner);
157	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
158	        headers.setLocation(UriComponentsBuilder.newInstance()
159	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
160	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
166	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
167	        if (currentOwner == null) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        currentOwner.setAddress(ownerFieldsDto.getAddress());
171	        currentOwner.setCity(ownerFieldsDto.getCity());
172	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
173	        currentOwner.setLastName(ownerFieldsDto.getLastName());
174	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
175	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
176	        this.clinicService.saveOwner(currentOwner);
177	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Transactional
182	    @Override
183	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
184	        Owner owner = this.clinicService.findOwnerById(ownerId);
185	        if (owner == null) {
186	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
187	        }
188	        this.clinicService.deleteOwner(owner);
189	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
190	    }
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Override
194	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
195	        Owner owner = this.clinicService.findOwnerById(ownerId);
196	        if (owner == null) {
197	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
198	        }
199	        HttpHeaders headers = new HttpHeaders();
200	        Pet pet = petMapper.toPet(petFieldsDto);
201	        owner.setId(ownerId);
202	        pet.setOwner(owner);
203	        pet.getType().setName(null);
204	        this.clinicService.savePet(pet);
205	        PetDto petDto = petMapper.toPetDto(pet);
206	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
207	            .buildAndExpand(pet.getId()).toUri());
208	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
209	    }
210	
211	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
212	    @Override
213	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
214	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
215	        if (currentOwner != null) {
216	            Pet currentPet = this.clinicService.findPetById(petId);
217	            if (currentPet != null) {
218	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
219	                currentPet.setName(petFieldsDto.getName());
220	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
221	                this.clinicService.savePet(currentPet);
222	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
223	            }
224	        }
225	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
226	    }
227	
228	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
229	    @Override
230	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
231	        HttpHeaders headers = new HttpHeaders();
232	        Visit visit = visitMapper.toVisit(visitFieldsDto);
233	        Pet pet = new Pet();
234	        pet.setId(petId);
235	        visit.setPet(pet);
236	        this.clinicService.saveVisit(visit);
237	        VisitDto visitDto = visitMapper.toVisitDto(visit);
238	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
239	            .buildAndExpand(visit.getId()).toUri());
240	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
241	    }
242	
243	
244	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
245	    @Override
246	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
247	        Owner owner = this.clinicService.findOwnerById(ownerId);
248	        if (owner != null) {
249	            Pet pet = owner.getPet(petId);
250	            if (pet != null) {
251	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
252	            }
253	        }
254	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
255	    }
256	
257	    /**
258	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
259	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
260	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
261	     *
262	     * @param ownerFieldsDto the submitted owner fields
263	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
264	     *                                     name of every offending field
265	     */
266	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
267	        List<String> missingFields = new ArrayList<>();
268	        if (isBlank(ownerFieldsDto.getFirstName())) {
269	            missingFields.add("firstName");
270	        }
271	        if (isBlank(ownerFieldsDto.getLastName())) {
272	            missingFields.add("lastName");
273	        }
274	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
275	            missingFields.add("address");
276	        }
277	        if (isBlank(ownerFieldsDto.getCity())) {
278	            missingFields.add("city");
279	        }
280	        if (isBlank(ownerFieldsDto.getTelephone())) {
281	            missingFields.add("telephone");
282	        }
283	        if (!missingFields.isEmpty()) {
284	            throw new InvalidOwnerFieldsException(missingFields);
285	        }
286	    }
287	
288	    private boolean isBlank(String value) {
289	        return value == null || value.isBlank();
290	    }
291	
292	    /**
293	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
294	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
295	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
296	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
297	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
298	     *
299	     * @param telephone the raw telephone value submitted by the client
300	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
301	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
302	     *                                     400 response
303	     */
304	    private String normalizeTelephone(String telephone) {
305	        String e164 = toE164(telephone);
306	        if (e164 == null) {
307	            throw new InvalidOwnerFieldsException(List.of("telephone"));
308	        }
309	        return e164;
310	    }
311	
312	    /**
313	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
314	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
315	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
316	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits.
317	     *
318	     * @param telephone the raw telephone value, possibly {@code null}
319	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
320	     */
321	    private String toE164(String telephone) {
322	        if (telephone == null) {
323	            return null;
324	        }
325	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
326	        boolean hasPlus = cleaned.startsWith("+");
327	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
328	        String nationalSignificant = hasPlus
329	            ? digits
330	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
331	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
332	            return null;
333	        }
334	        return "+" + nationalSignificant;
335	    }
336	
337	    /**
338	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
339	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
340	     * returned value is that address lower-cased.
341	     *
342	     * @param email the raw email value submitted by the client, or {@code null} if omitted
343	     * @return the lower-cased email, or {@code null} if none was supplied
344	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
345	     *                                     yielding a 400 response
346	     */
347	    private String normalizeEmail(String email) {
348	        if (email == null) {
349	            return null;
350	        }
351	        if (!EMAIL_PATTERN.matcher(email).matches()) {
352	            throw new InvalidOwnerFieldsException(List.of("email"));
353	        }
354	        return email.toLowerCase(Locale.ROOT);
355	    }
356	
357	    /**
358	     * Counts the existing owners that, before this create, already share the given first name and
359	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
360	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
361	     * been saved yet, so it is never included in the count.
362	     *
363	     * @param firstName the first name of the owner being created
364	     * @param lastName  the last name of the owner being created
365	     * @return the number of existing owners sharing both names
366	     */
367	    private int countNamesakes(String firstName, String lastName) {
368	        String normalizedFirstName = normalizeForComparison(firstName);
369	        String normalizedLastName = normalizeForComparison(lastName);
370	        return (int) this.clinicService.findAllOwners().stream()
371	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
372	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
373	            .count();
374	    }
375	
376	    /**
377	     * Builds the owner's {@code customerCode}, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3}
378	     * is the upper-cased first three letters of the city, {@code LAST3} the upper-cased first three
379	     * letters of the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one
380	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
381	     *
382	     * @param city     the owner's city
383	     * @param lastName the owner's last name
384	     * @return the formatted customer code
385	     */
386	    private String generateCustomerCode(String city, String lastName) {
387	        String city3 = first3Letters(city);
388	        String last3 = first3Letters(lastName);
389	        int sequence = countOwnersInCity(city) + 1;
390	        return String.format("%s-%s-%04d", city3, last3, sequence);
391	    }
392	
393	    /**
394	     * Returns the upper-cased first three letters of the given value, with any non-letter characters
395	     * removed first, used to build the city and last-name segments of a {@code customerCode}.
396	     *
397	     * @param value the value to abbreviate
398	     * @return the upper-cased first three letters, or fewer if the value has fewer letters
399	     */
400	    private String first3Letters(String value) {
401	        String letters = value.replaceAll("[^\\p{L}]", "");
402	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
403	    }
404	
405	    /**
406	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
407	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
408	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
409	     * has not been saved yet, so it is never included in the count.
410	     *
411	     * @param city the city of the owner being created
412	     * @return the number of existing owners in that city
413	     */
414	    private int countOwnersInCity(String city) {
415	        String normalizedCity = normalizeForComparison(city);
416	        return (int) this.clinicService.findAllOwners().stream()
417	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
418	            .count();
419	    }
420	
421	    /**
422	     * Rejects creation of an owner whose city already contains the maximum number of owners
423	     * ({@value #CITY_CAPACITY}). Owners are counted per city case-insensitively with surrounding and
424	     * internal whitespace collapsed, consistent with the other owner-field comparisons.
425	     *
426	     * @param city the city of the owner being created
427	     * @throws OwnerCityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more
428	     *                                      owners, yielding a 409 Conflict response
429	     */
430	    private void rejectCityAtCapacity(String city) {
431	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
432	            throw new OwnerCityAtCapacityException(city);
433	        }
434	    }
435	
436	    /**
437	     * Rejects creation of an owner whose E.164 telephone is already used by any other owner. Stored
438	     * telephones are converted to E.164 here as well so the comparison is independent of the format
439	     * each owner was originally saved with; a stored value that cannot form a valid E.164 number is
440	     * ignored rather than matched.
441	     *
442	     * @param telephone the E.164 telephone of the owner being created
443	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone,
444	     *                                          yielding a 409 Conflict response
445	     */
446	    private void rejectDuplicateTelephone(String telephone) {
447	        boolean inUse = this.clinicService.findAllOwners().stream()
448	            .map(Owner::getTelephone)
449	            .map(this::toE164)
450	            .anyMatch(telephone::equals);
451	        if (inUse) {
452	            throw new DuplicateOwnerTelephoneException(telephone);
453	        }
454	    }
455	
456	    /**
457	     * Rejects creation of an owner whose last name and address both match an existing owner's,
458	     * which marks them as belonging to the same household. Both the last name and the address are
459	     * compared case-insensitively with surrounding and internal whitespace collapsed, so values
460	     * that differ only in letter case or spacing are still treated as a match.
461	     *
462	     * @param lastName the last name of the owner being created
463	     * @param address  the address of the owner being created
464	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
465	     *                                          address, yielding a 409 Conflict response
466	     */
467	    private void rejectDuplicateHousehold(String lastName, String address) {
468	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
469	            throw new DuplicateOwnerHouseholdException(lastName, address);
470	        }
471	    }
472	
473	    /**
474	     * Finds every existing owner belonging to the household identified by the given last name and
475	     * address — that is, the owners the duplicate-household rule rejects and the {@code sharesHousehold}
476	     * opt-in joins. Both the last name and the address are compared case-insensitively with surrounding
477	     * and internal whitespace collapsed, so values that differ only in letter case or spacing still
478	     * match. This single definition of household membership is shared by {@link #rejectDuplicateHousehold}
479	     * and {@link #assignHousehold}.
480	     *
481	     * @param lastName the last name of the owner being created
482	     * @param address  the address of the owner being created
483	     * @return the existing owners in that household, or an empty list if there are none
484	     */
485	    private List<Owner> findHouseholdMembers(String lastName, String address) {
486	        String normalizedLastName = normalizeForComparison(lastName);
487	        String normalizedAddress = normalizeAddress(address);
488	        return this.clinicService.findAllOwners().stream()
489	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
490	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
491	            .toList();
492	    }
493	
494	    /**
495	     * Enrolls a newly created owner into the household of any existing owner that shares its last
496	     * name and address, so an owner that opts in via {@code sharesHousehold} is accepted instead of
497	     * rejected as a duplicate. Last name and address are compared case-insensitively with collapsed
498	     * whitespace. When at least one such owner already exists, every member of the household — the
499	     * existing owners and the new one — is assigned the same stable {@code householdId}; if a member
500	     * already carries one it is reused, otherwise a new identifier derived from the shared last name
501	     * and address is created and back-filled onto the existing members. When no owner yet lives at
502	     * that address under the same last name no identifier is assigned and the owner is created alone.
503	     *
504	     * @param newOwner the owner being created, whose {@code householdId} will be set on a match
505	     * @param lastName the last name of the owner being created
506	     * @param address  the address of the owner being created
507	     * @return the assigned {@code householdId}, or {@code null} if there was no household to join
508	     */
509	    private String assignHousehold(Owner newOwner, String lastName, String address) {
510	        List<Owner> members = findHouseholdMembers(lastName, address);
511	        if (members.isEmpty()) {
512	            return null;
513	        }
514	        String householdId = members.stream()
515	            .map(Owner::getHouseholdId)
516	            .filter(existing -> existing != null && !existing.isBlank())
517	            .findFirst()
518	            .orElseGet(() -> generateHouseholdId(normalizeForComparison(lastName), normalizeAddress(address)));
519	        for (Owner member : members) {
520	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
521	                member.setHouseholdId(householdId);
522	                this.clinicService.saveOwner(member);
523	            }
524	        }
525	        newOwner.setHouseholdId(householdId);
526	        return householdId;
527	    }
528	
529	    /**
530	     * Derives a stable household identifier, formatted {@code 'HH-<HEX12>'}, where {@code HEX12} is
531	     * the first twelve upper-cased hex characters of the SHA-256 digest of the normalized last name
532	     * and address joined by a {@code '|'}. The same last name and address therefore always yield the
533	     * same identifier, so members of one household share a single value.
534	     *
535	     * @param normalizedLastName the household's last name, already normalized for comparison
536	     * @param normalizedAddress  the household's address, already normalized for comparison
537	     * @return the derived household identifier
538	     */
539	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
540	        try {
541	            byte[] digest = MessageDigest.getInstance("SHA-256")
542	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
543	            StringBuilder hex = new StringBuilder(digest.length * 2);
544	            for (byte b : digest) {
545	                hex.append(String.format("%02x", b));
546	            }
547	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
548	        } catch (NoSuchAlgorithmException e) {
549	            throw new IllegalStateException("SHA-256 algorithm not available", e);
550	        }
551	    }
552	
553	    /**
554	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
555	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
556	     * the result is lower-cased.
557	     *
558	     * @param value the value to normalize, possibly {@code null}
559	     * @return the normalized value, or an empty string if {@code value} is {@code null}
560	     */
561	    private String normalizeForComparison(String value) {
562	        if (value == null) {
563	            return "";
564	        }
565	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
566	    }
567	
568	    /**
569	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
570	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
571	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
572	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
573	     * This normalized value is what gets stored and returned, and it is the form every address
574	     * comparison (household duplicate detection and the shared household id) uses.
575	     *
576	     * @param address the raw address value submitted by the client, possibly {@code null}
577	     * @return the normalized address, or an empty string if {@code address} is {@code null}
578	     */
579	    private String normalizeAddress(String address) {
580	        if (address == null) {
581	            return "";
582	        }
583	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
584	        if (collapsed.isEmpty()) {
585	            return collapsed;
586	        }
587	        String[] tokens = collapsed.split(" ");
588	        StringBuilder normalized = new StringBuilder(collapsed.length());
589	        for (int i = 0; i < tokens.length; i++) {
590	            if (i > 0) {
591	                normalized.append(' ');
592	            }
593	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
594	        }
595	        return normalized.toString();
596	    }
597	}
